from fractions import Fraction
lower=(2,2)+(0,)*7; upper=(4,)*9

def P(x):
    x=tuple(x); return x+(0,)*(9-len(x))
def show(x):
    x=list(x)
    while x and x[-1]==0:x.pop()
    return ''.join(map(str,x)) or '0'
def parts(d):
 out=[]
 def f(i,last,left,a):
  if i==9:
   if left==0:out.append(tuple(a))
   return
  for z in range(min(upper[i],last,left),lower[i]-1,-1):f(i+1,z,left-z,a+[z])
 f(0,99,d,[]);return out
def hs(l,m):return all(m[i]>=l[i]>=m[i+1] for i in range(8)) and m[8]>=l[8]
def determinant(A):
 n=len(A)
 if n==0:return 1
 A=[[Fraction(z) for z in r] for r in A];d=Fraction(1)
 for k in range(n):
  z=next(i for i in range(k,n) if A[i][k])
  if z!=k:A[k],A[z]=A[z],A[k];d=-d
  p=A[k][k];d*=p
  for i in range(k+1,n):
   q=A[i][k]/p
   for j in range(k,n):A[i][j]-=q*A[k][j]
 return int(d)
def inverse(A):
 n=len(A);X=[[Fraction(A[i][j]) for j in range(n)]+[Fraction(i==j) for j in range(n)] for i in range(n)]
 for k in range(n):
  z=next(i for i in range(k,n) if X[i][k]);X[k],X[z]=X[z],X[k]
  p=X[k][k];X[k]=[v/p for v in X[k]]
  for i in range(n):
   if i!=k:
    q=X[i][k];X[i]=[X[i][j]-q*X[k][j] for j in range(2*n)]
 return [r[n:] for r in X]
surv={4:[P((2,2))],5:[P((3,2))],6:[P((4,2)),P((3,3))],7:[P((4,3))],8:[P((4,4))]}
chosen={4:[],5:[1],6:[1,2,3],7:[1,2,4,5,7,8],8:[1,15,9,2,14,11,3,5,6,7]}
R={}
for d in range(4,9):
 cols=parts(d); rows=[];labs=[]
 for h in range(1,5):
  for lam in parts(d-h):
   r=[int(hs(lam,mu)) for mu in cols]
   if any(r):rows.append(r);labs.append((h,lam))
 ss=[cols.index(x) for x in surv[d]]; non=[i for i in range(len(cols)) if i not in ss]; sel=[i-1 for i in chosen[d]]
 A=[[rows[i][j] for j in non] for i in sel]
 print('D',d,'BASIS',[show(x) for x in cols])
 print('ROWS',[(h,show(x)) for h,x in labs]);print('M',rows)
 print('SELECT',chosen[d],'NON',[show(cols[j]) for j in non],'MINOR',A,'DET',determinant(A))
 R[d]=(cols,rows,sel,ss,non,A)
def coord(mu):
 mu=P(mu);d=sum(mu);cols,rows,sel,ss,non,A=R[d]
 if mu in surv[d]:return [int(mu==x) for x in surv[d]]
 # Relation block [A | S] says non-column classes=-A^{-1}S survivor classes.
 S=[[rows[i][j] for j in ss] for i in sel];inv=inverse(A);k=non.index(cols.index(mu))
 return [int(-sum(inv[k][i]*S[i][a] for i in range(len(non)))) for a in range(len(ss))]
F1=[(2,2),(3,2),(4,2),(3,3),(4,3),(4,4)]
F2=[(2,2),(2,2,1),(2,2,2),(2,2,1,1),(2,2,2,1),(2,2,2,2)]
off={4:0,5:1,6:2,7:4,8:5}
def CM(F):
 out=[[0]*6 for _ in range(6)]
 for j,x in enumerate(F):
  w=coord(x);o=off[sum(x)]
  for a,z in enumerate(w):out[o+a][j]=z
 return out
I=CM(F1);C=CM(F2)
print('F1COORD',I,'DET',determinant(I));print('F2COORD',C,'DET',determinant(C))
for x in F2[1:]:print('REL',show(P(x)),coord(x))
